<script setup lang="ts">
import axios from 'axios';
import { onMounted, onUnmounted, ref, watch } from 'vue';
import { api, errorMessage } from '../api';
import { amount, decimalInput } from '../catalog';
import { clearPending, readPending, savePending } from '../lib/pendingRequests';
import type { Store } from '../types';
import AppDialog from './AppDialog.vue';

type Employee = { id:number; employee_code:string; full_name:string; phone?:string|null; email?:string|null; status:string; store_ids?:number[] };
type Plan = { id:number; pay_type:'salary'|'commission'; fixed_salary:string|null; salary_period:string|null; commission_rate:string|null; currency:string; effective_from:string; effective_to:string|null };
type SellerSummary = { currency:string; orders_count:number; sales_net:string; collected_net:string; earned_commission:string };
type Pending = { kind:'employee'|'edit'|'plan'; employeeId?:number; payload:Record<string,unknown>&{request_key:string} };
const props = defineProps<{ store?:Store; stores?:Store[]; actorId:number }>();
const emit = defineEmits<{ 'context-locked':[boolean] }>();
const root = `/business/stores/${props.store?.id}/employees`;
const journal = `bshop:employees:${props.actorId}:${props.store?.id}`;
const employees=ref<Employee[]>([]); const selected=ref<Employee|null>(null); const plans=ref<Plan[]>([]); const sellerSummary=ref<SellerSummary|null>(null); const page=ref(1); const lastPage=ref(1);
const loading=ref(false); const plansLoading=ref(false); const busy=ref(false); const error=ref(''); const notice=ref(''); const modal=ref<'employee'|'edit'|'plan'|null>(null); const opener=ref<HTMLElement|null>(null); const pending=ref<Pending|null>(null);
const name=ref(''); const code=ref(''); const empStatus=ref<'active'|'inactive'>('active'); const assignedStores=ref<number[]>([]); const type=ref<'salary'|'commission'>('commission'); const amountValue=ref(''); const period=ref('weekly'); const from=ref(''); const until=ref(''); const endOpen=ref(false);
let alive=true; let listToken=0; let planToken=0;
watch([busy,pending],()=>emit('context-locked',busy.value||!!pending.value),{immediate:true});
async function load(target=1){const token=++listToken;loading.value=true;try{const result=(await api.get(root,{params:{page:target}})).data;if(alive&&token===listToken){employees.value=result.data;page.value=result.meta.current_page;lastPage.value=result.meta.last_page;error.value='';}}catch(e){if(alive&&token===listToken)error.value=errorMessage(e);}finally{if(alive&&token===listToken)loading.value=false;}}
async function select(employee:Employee,internal=false){if(!internal&&(busy.value||pending.value))return;selected.value=employee;plans.value=[];sellerSummary.value=null;const token=++planToken;plansLoading.value=true;error.value='';try{const result=(await api.get(`${root}/${employee.id}/plans`)).data;if(alive&&token===planToken){plans.value=result.data;sellerSummary.value=result.summary||null;}}catch(e){if(alive&&token===planToken)error.value=errorMessage(e);}finally{if(alive&&token===planToken)plansLoading.value=false;}}
function open(kind:'employee'|'edit'|'plan',event:Event){opener.value=event.currentTarget as HTMLElement;error.value='';notice.value='';modal.value=kind;if(kind==='employee'){name.value='';code.value='';}else if(kind==='edit'&&selected.value){name.value=selected.value.full_name;code.value=selected.value.employee_code;empStatus.value=selected.value.status==='inactive'?'inactive':'active';assignedStores.value=selected.value.store_ids?.length?[...selected.value.store_ids]:(props.store?[props.store.id]:[]);}else{type.value='commission';amountValue.value='';period.value='weekly';from.value='';until.value='';endOpen.value=false;}}
function submitEmployee(){send({kind:'employee',payload:{request_key:crypto.randomUUID(),employee_code:code.value,full_name:name.value}});}
function submitEdit(){if(!selected.value)return;send({kind:'edit',employeeId:selected.value.id,payload:{request_key:crypto.randomUUID(),employee_code:code.value,full_name:name.value,status:empStatus.value,...(assignedStores.value.length?{store_ids:assignedStores.value}:{})}});}
function submitPlan(){if(!selected.value)return;const data:Pending={kind:'plan',employeeId:selected.value.id,payload:{request_key:crypto.randomUUID(),pay_type:type.value,effective_from:from.value,effective_to:until.value||null,end_open_plan:endOpen.value,...(type.value==='salary'?{fixed_salary:decimalInput(amountValue.value),salary_period:period.value}:{commission_rate:decimalInput(amountValue.value)})}};send(data);}
async function send(operation?:Pending){if(busy.value)return;error.value='';notice.value='';if(!pending.value){if(!operation)return;try{savePending(journal,operation as unknown as Record<string,unknown>);pending.value=operation;}catch{error.value='No se pudo guardar la recuperación. No se enviaron cambios.';return;}}busy.value=true;const action=pending.value;
    try{const url=action.kind==='employee'?root:action.kind==='edit'?`${root}/${action.employeeId}`:`${root}/${action.employeeId}/plans`;const response=action.kind==='edit'?await api.patch(url,action.payload):await api.post(url,action.payload);const result=response.data.data;if(!alive)return;pending.value=null;try{clearPending(journal);}catch{}modal.value=null;notice.value=action.kind==='employee'?'Vendedor guardado.':action.kind==='edit'?'Vendedor actualizado.':'Contrato guardado. No se ha generado ningún pago ni comisión.';await load();const employee=action.kind==='employee'||action.kind==='edit'?result.employee:(selected.value?.id===action.employeeId?selected.value:employees.value.find(item=>item.id===action.employeeId));if(employee)await select(employee,true);}
    catch(e){if(alive){error.value=errorMessage(e);modal.value=null;if(axios.isAxiosError(e)&&e.response&&[403,404,409,422].includes(e.response.status)){pending.value=null;try{clearPending(journal);}catch{}}}}
    finally{if(alive)busy.value=false;}}
onMounted(()=>{if(props.store)load();const saved=readPending(journal) as unknown as Pending|null;if(saved&&['employee','plan'].includes(saved.kind)&&typeof saved.payload?.request_key==='string'&&(saved.kind==='employee'||Number.isInteger(saved.employeeId)))pending.value=saved;});
onUnmounted(()=>{alive=false;++listToken;++planToken;emit('context-locked',false);});
</script>
<template>
    <div v-if="store" class="employees-workspace">
        <p v-if="error&&!modal" class="notice error" role="alert">{{ error }}</p><p v-if="notice" class="notice success" role="status">{{ notice }}</p>
        <div v-if="pending" class="notice" role="status">Hay una operación de vendedor sin confirmar. <button type="button" class="button secondary" :disabled="busy" @click="send()">Reintentar la misma operación</button></div>
        <section class="panel" aria-label="Vendedores"><div class="panel-heading"><div><h2>Vendedores</h2><p class="muted">Personal asignado a {{ store.name }}.</p></div><button type="button" class="button primary" :disabled="busy||!!pending" @click="open('employee',$event)">Nuevo vendedor</button></div>
            <p v-if="loading" role="status">Consultando vendedores…</p><p v-else-if="!employees.length&&!error" class="muted">No hay vendedores registrados en esta sucursal.</p>
            <div class="employee-list"><button v-for="employee in employees" :key="employee.id" type="button" class="employee-card" :disabled="busy||!!pending" :aria-pressed="selected?.id===employee.id" @click="select(employee)"><strong>{{ employee.full_name }}</strong><span>{{ employee.employee_code }} · {{ employee.status==='active'?'Activo':'Inactivo' }}</span></button></div>
            <div v-if="lastPage>1" class="actions"><button type="button" class="button secondary" :disabled="busy||!!pending||page<=1" @click="load(page-1)">Anterior</button><span>{{ page }}/{{ lastPage }}</span><button type="button" class="button secondary" :disabled="busy||!!pending||page>=lastPage" @click="load(page+1)">Siguiente</button></div>
            <button type="button" class="button secondary" :disabled="busy||!!pending||loading" @click="load(page)">Actualizar vendedores</button>
        </section>
        <section v-if="selected" class="panel" aria-label="Contratos del vendedor"><div class="panel-heading"><div><h2>Contratos de {{ selected.full_name }}</h2><p class="muted">Las fechas históricas y los importes anteriores se conservan.</p></div><div class="actions"><button type="button" class="button secondary" :disabled="busy||!!pending" @click="open('edit',$event)">Editar vendedor</button><button type="button" class="button primary" :disabled="busy||!!pending||plansLoading||!!error" @click="open('plan',$event)">Nuevo contrato</button></div></div>
            <div v-if="sellerSummary" class="seller-summary-grid" aria-label="Resumen comercial del vendedor">
                <div><span>Pedidos atribuidos</span><strong>{{ sellerSummary.orders_count }}</strong></div>
                <div><span>Ventas netas</span><strong>{{ amount(sellerSummary.sales_net, sellerSummary.currency) }}</strong></div>
                <div><span>Cobrado</span><strong>{{ amount(sellerSummary.collected_net, sellerSummary.currency) }}</strong></div>
                <div><span>Comisión devengada</span><strong>{{ amount(sellerSummary.earned_commission, sellerSummary.currency) }}</strong></div>
            </div>
            <p v-if="plansLoading" role="status">Consultando contratos…</p><p v-else-if="!plans.length&&!error" class="muted">No hay contratos registrados.</p><button v-if="error&&!plansLoading" type="button" class="button secondary" :disabled="busy||!!pending" @click="select(selected)">Reintentar contratos</button><article v-for="plan in plans" :key="plan.id" class="employee-plan"><strong>{{ plan.pay_type==='salary'?'Sueldo fijo':'Comisión' }}</strong><span v-if="plan.pay_type==='salary'">{{ amount(String(plan.fixed_salary),plan.currency) }} · {{ plan.salary_period==='weekly'?'semanal':plan.salary_period==='biweekly'?'quincenal':'mensual' }}</span><span v-else>{{ plan.commission_rate }} % sobre productos netos cobrados</span><span>{{ plan.effective_from }} al {{ plan.effective_to||'sin fecha final' }}</span></article>
            <p class="notice">El registro de contratos no calcula nómina ni genera pagos o comisiones todavía.</p>
        </section>
        <AppDialog :open="modal==='employee'" title="Nuevo vendedor" :busy="busy||!!pending" :return-focus="opener" @close="modal=null"><form id="employee-form" class="form-stack" @submit.prevent="submitEmployee"><label>Nombre<input v-model="name" required maxlength="180" autocomplete="name" :disabled="busy||!!pending"></label><label>Código<input v-model="code" required maxlength="40" pattern="[A-Za-z0-9_-]+" :disabled="busy||!!pending"></label></form><template #footer><button type="button" class="button secondary" :disabled="busy" @click="modal=null">Cancelar</button><button type="submit" form="employee-form" class="button primary" :disabled="busy||!!pending">Guardar vendedor</button></template></AppDialog>
        <AppDialog :open="modal==='edit'" title="Editar vendedor" :busy="busy||!!pending" :return-focus="opener" @close="modal=null"><form id="employee-edit-form" class="form-stack" @submit.prevent="submitEdit"><label>Nombre<input v-model="name" required maxlength="180" :disabled="busy||!!pending"></label><label>Código<input v-model="code" required maxlength="40" pattern="[A-Za-z0-9_-]+" :disabled="busy||!!pending"></label><label>Estado<select v-model="empStatus" :disabled="busy||!!pending"><option value="active">Activo</option><option value="inactive">Inactivo</option></select></label><fieldset v-if="stores&&stores.length>1" class="form-fields"><legend>Sucursales asignadas</legend><label v-for="branch in stores" :key="branch.id" class="check-label"><input v-model="assignedStores" type="checkbox" :value="branch.id" :disabled="busy||!!pending||branch.id===store?.id"> {{ branch.name }}</label></fieldset></form><template #footer><button type="button" class="button secondary" :disabled="busy" @click="modal=null">Cancelar</button><button type="submit" form="employee-edit-form" class="button primary" :disabled="busy||!!pending">Guardar cambios</button></template></AppDialog>
        <AppDialog :open="modal==='plan'" title="Nuevo contrato" :busy="busy||!!pending" :return-focus="opener" @close="modal=null"><form id="employee-plan-form" class="form-stack" @submit.prevent="submitPlan"><label>Modalidad<select v-model="type" :disabled="busy||!!pending"><option value="commission">Comisión</option><option value="salary">Sueldo fijo</option></select></label><label>{{ type==='salary'?'Sueldo por período':'Porcentaje de comisión' }}<input v-model="amountValue" required inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,4})?" :disabled="busy||!!pending"></label><label v-if="type==='salary'">Período de sueldo<select v-model="period" :disabled="busy||!!pending"><option value="weekly">Semanal</option><option value="biweekly">Quincenal</option><option value="monthly">Mensual</option></select></label><label>Vigente desde<input v-model="from" type="date" required :disabled="busy||!!pending"></label><label>Vigente hasta (opcional)<input v-model="until" type="date" :min="from" :disabled="busy||!!pending"></label><label class="check-label"><input v-model="endOpen" type="checkbox" :disabled="busy||!!pending"> Finalizar el contrato abierto el día anterior al nuevo inicio</label><p class="muted">Los contratos posteriores deben comenzar en el futuro. El cierre del contrato abierto requiere la confirmación anterior.</p></form><template #footer><button type="button" class="button secondary" :disabled="busy" @click="modal=null">Cancelar</button><button type="submit" form="employee-plan-form" class="button primary" :disabled="busy||!!pending">Guardar contrato</button></template></AppDialog>
    </div>
    <p v-else class="notice">Selecciona una sucursal autorizada para consultar vendedores.</p>
</template>
<style scoped>.employees-workspace{display:grid;gap:24px}.employee-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:12px;margin:18px 0}.employee-card{min-height:80px;display:grid;gap:6px;text-align:left;padding:16px;border:1px solid #ddd5ec;border-radius:12px;background:#fff;overflow-wrap:anywhere}.employee-card[aria-pressed=true]{border-color:#7050ca;background:#f4efff}.seller-summary-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:14px 0;padding:14px;background:#f7f4fc;border:1px solid #e4dcf2;border-radius:12px}.seller-summary-grid span{display:block;font-size:12px;color:#6d617d}.seller-summary-grid strong{font-size:18px;font-weight:750;white-space:nowrap}.employee-plan{display:grid;gap:5px;padding:16px 0;border-bottom:1px solid #e7e0ef;overflow-wrap:anywhere}.employees-workspace .button,.employee-card{min-height:48px}.employees-workspace .check-label{min-height:48px}</style>
